#pragma once
namespace esphome::clock_setup {
static const char SETUP_PAGE[] = R"page(<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SucroClock · Glucose Setup</title><link rel="icon" type="image/png" href="/icon.png"><link rel="apple-touch-icon" href="/icon.png">
<style nonce="@TOKEN@">body{font:17px system-ui,sans-serif;background:#10151d;color:#edf2f7;max-width:560px;margin:40px auto;padding:0 22px}.brand{display:flex;align-items:center;gap:12px}.brand img{border-radius:22%}h1{font-size:28px}h2{font-size:21px}label{display:block;margin-top:18px}input,select,button{font:inherit;box-sizing:border-box;width:100%;padding:12px;border-radius:8px;border:1px solid #596677;background:#1d2734;color:inherit;margin-top:8px}button{cursor:pointer;background:#245d9b;border:0;margin-top:20px}button.secondary{background:#344151}p{line-height:1.5;color:#c1cbd7}#message,#sugarStatus{white-space:pre-wrap}small{font-size:14px;color:#b7c4d4}a{color:#9ac8ff}[hidden]{display:none!important}</style></head>
<body><div class="brand"><img src="/icon.png" alt="" width="44" height="44"><h1>SucroClock</h1></div><h2>Glucose setup</h2><p>Save settings for each provider separately. Save &amp; Test checks that provider without changing the active source or display mode.</p>
<label>Configure provider<select id="provider"><option value="dexcom">Dexcom Share</option><option value="libre">LibreLinkUp</option><option value="nightscout">Nightscout</option><option value="sugarsense">SugarSense</option></select></label>
<section id="sugarBox" hidden><p>Pair the clock with your SugarSense account. Approve the code on SugarSense's website; no sensor password is needed here.</p><p id="sugarStatus" role="status"></p><p id="sugarCode" style="font-size:28px;letter-spacing:4px"></p><p><a id="sugarLink" href="https://app.sugarsense.io/display" target="_blank" rel="noopener noreferrer">Open SugarSense pairing</a></p><button id="sugarPair" type="button">Start pairing</button><button id="sugarDisconnect" class="secondary" type="button">Disconnect / cancel pairing</button><small>Pairing does not change the active source. Once paired, select SugarSense and Display on the controls page. This shows your own account's reading, using the clock's configured colors and ranges.</small></section>
<form id="settings"><label><span id="userLabel">Dexcom username</span><input id="username" autocomplete="username" maxlength="256" required></label>
<label><span id="secretLabel">Password</span><input id="password" type="password" autocomplete="new-password" maxlength="256"></label><small id="secretNote">Leave blank to keep the saved secret.</small>
<label id="regionBox">Region<select id="region"></select></label>
<div id="libreBox" hidden><label>Linked person<select id="patient"><option value="">Automatic (one linked person only)</option></select></label><small>Test the connection to load linked people. Choose explicitly when more than one person is shared.</small><label>LibreLinkUp client version<input id="version" maxlength="15" value="4.16.0"></label><small>Use the current LibreLinkUp app version if Abbott requires an update.</small></div>
<div id="nsBox" hidden><label>Nightscout authentication<select id="mode"><option>Token</option><option>API Secret</option><option>Public</option></select></label><small>Use a read-only access token where available. Enter a base URL such as https://your-nightscout.example; no token in the URL. Public mode sends no authentication.</small></div>
<button id="save" type="submit">Save &amp; Test</button><button class="secondary" id="forget" type="button">Forget this provider's settings</button></form>
<p id="message" role="status">Loading settings…</p><small>Secrets stay on the clock and are never returned to this page. <a href="/">Clock and glucose controls</a></small>
<script nonce="@TOKEN@">
'use strict';
const csrf='@TOKEN@';const $=id=>document.getElementById(id);let state=null;let initialized=false;let waiting=false;let previousRevision=0;let lastChoices='';
function choosePerson(s,force){const choices=JSON.stringify(s.connections||[]);if(!force&&choices===lastChoices)return;const selected=force?(s.patient||''):$('patient').value;lastChoices=choices;$('patient').replaceChildren(new Option('Automatic (one linked person only)',''));for(const p of (s.connections||[]))$('patient').add(new Option(p.name||p.id,p.id));if(selected&&!Array.from($('patient').options).some(o=>o.value===selected))$('patient').add(new Option(selected,selected));$('patient').value=selected;}
function fill(){if(!state)return;const p=$('provider').value;const s=state.providers[p];$('sugarBox').hidden=p!=='sugarsense';$('settings').hidden=p==='sugarsense';if(p==='sugarsense'){initialized=true;return;}$('password').value='';$('username').value=p==='dexcom'?s.username:s.address;
$('userLabel').textContent=p==='dexcom'?'Dexcom publishing-account username':p==='libre'?'LibreLinkUp follower email':'Nightscout HTTPS base URL';$('secretLabel').textContent=p==='nightscout'?'Access token or API secret':'Password';
$('libreBox').hidden=p!=='libre';$('nsBox').hidden=p!=='nightscout';$('regionBox').hidden=p==='nightscout';$('region').replaceChildren();
for(const value of (p==='libre'?['Auto','US','EU','EU2','AE','AP','AU','CA','DE','FR','JP','LA','RU']:['US','Outside US','Japan']))$('region').add(new Option(value,value));$('region').value=s.region||'Auto';
if(p==='libre'){choosePerson(s,true);$('version').value=s.client_version||'4.16.0';}if(p==='nightscout')$('mode').value=s.mode||'Token';initialized=true;}
async function status(){try{const response=await fetch('/api/status',{cache:'no-store'});if(!response.ok)throw Error('Could not read clock settings.');state=await response.json();if(waiting&&state.revision===previousRevision)return;if(waiting){waiting=false;initialized=false;}if(!initialized)fill();const p=$('provider').value,s=state.providers[p];if(p==='sugarsense'){$('sugarStatus').textContent=s.pair_status+'\n'+s.test_status;$('sugarCode').textContent=s.code||'';$('sugarLink').hidden=!s.code;$('sugarLink').href=s.pair_url||'https://app.sugarsense.io/display';$('sugarPair').disabled=!!s.paired||!!s.pairing||!!s.code||waiting;$('message').textContent='Active source: '+state.source+'\n'+state.source_status;return;}if(p==='libre')choosePerson(s,false);$('secretNote').textContent=s.secret_saved?'Secret saved. Leave blank to keep it.':'No secret saved. Enter one unless Nightscout is public.';$('message').textContent=state.save_status+'\n'+s.test_status+'\nActive source: '+state.source+'\n'+state.source_status;}catch(e){$('message').textContent=e.message;}}
async function submit(forget){$('save').disabled=true;$('forget').disabled=true;$('provider').disabled=true;try{const current=await fetch('/api/status',{cache:'no-store'});if(!current.ok)throw Error('Could not read settings.');previousRevision=(await current.json()).revision;const p=$('provider').value;
const payload={provider:p,username:$('username').value,password:$('password').value,region:p==='nightscout'?'Auto':$('region').value,patient:p==='libre'?$('patient').value:'',mode:$('mode').value,client_version:$('version').value||'4.16.0',forget:forget};
const response=await fetch('/api/save',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(payload)});if(!response.ok)throw Error((await response.json()).error||'Could not save settings.');$('password').value='';waiting=true;$('message').textContent='Applying settings…';await status();}catch(e){$('message').textContent=e.message;}finally{$('save').disabled=false;$('forget').disabled=false;$('provider').disabled=false;}}
async function sugarAction(forget){$('sugarPair').disabled=true;$('sugarDisconnect').disabled=true;try{const response=await fetch('/api/save',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({provider:'sugarsense',forget:forget})});if(!response.ok)throw Error((await response.json()).error||'Could not update pairing.');await new Promise(resolve=>setTimeout(resolve,500));await status();}catch(e){$('message').textContent=e.message;}finally{$('sugarDisconnect').disabled=false;}}
$('sugarPair').addEventListener('click',()=>sugarAction(false));$('sugarDisconnect').addEventListener('click',()=>{if(confirm('Disconnect SugarSense or cancel pairing? Other provider settings stay saved.'))sugarAction(true);});
$('provider').addEventListener('change' ,()=>{initialized=false;fill();status();});$('settings').addEventListener('submit',e=>{e.preventDefault();submit(false);});$('forget').addEventListener('click',()=>{if(confirm('Forget the saved settings for this provider only?'))submit(true);});status();setInterval(status,4000);
</script></body></html>)page";
}
